export const SKILL_SOURCES: Readonly<Record<string, string>> = {
  "cliffhanger": "---\nname: cliffhanger\ndescription: \"章尾收束：章末按本章计划的收法写——悬念、一句对白、安静的画面或日常动作、人物的决定、情绪落点或小幽默；不每章都停在悬念的定格上，最近几章用过的收法换一种；不写总结、感悟或预告。写每一章的结尾时使用。\"\nmetadata:\n  title: \"章尾收束\"\n  version: \"3\"\n  order: \"7\"\n---\n\n一本书两百章都在章末停住一个惊险的画面，读者就知道这是机器排的。章尾有六种收法，按本章计划里定的那一种写；计划没定时自己选一种，但不要与最近几章相同。\n\n- 悬念：停在一个未解的问题、刚揭开一角的发现，或马上就要发生的冲突上。这种收法最省力也最容易用滥，一本书里不要超过三分之一的章。\n- 一句对白：以人物的一句话收尾，话里带着没说完的意思，不加旁白解释。\n- 安静的画面或日常动作：停在一个安静的画面、一件日常的小事上（添一把柴、把碗洗了、灯灭了），不制造悬念，让读者缓一口气。\n- 人物的决定：人物在章末拿定一个主意或迈出一步，读者知道他接下来要去做什么，而不是看见他“陷入沉思”。\n- 情绪落点：停在人物的一个情绪上，用动作或细节写出来，不直接说出情绪的名字，不替读者感慨。\n- 小幽默：以一点轻松或自嘲收尾，松一口气，尤其在连着几章紧张之后。\n\n不管哪一种，章末都不要写总结、感悟或预告（“这一夜，很多事都变了”“他不知道，更大的风暴正在等着他”）；也不要把最后一句写成影视分镜式的定格长句——定格只是六种里的一种，不是每章的必选。\n",
  "dialogue": "---\nname: dialogue\ndescription: \"对话与人物声音：每个人物有自己的说话方式，对话带潜台词，穿插动作与停顿，不一问一答地交代信息；对白不承担大段的前情交代，重伤、仓促、对立的人说不了长话；对话要占到本章该有的分量，让人物用自己的话推动情节。写人物对话时使用。\"\nmetadata:\n  title: \"对话与人物声音\"\n  version: \"3\"\n  order: \"5\"\n---\n\n- 每个人物说话都有自己的用词、句子长短与节奏，参照设定中的说话风格：粗人说短句，读书人绕弯子，官面上的人说套话，孩子问个不停。两个人的台词互换一下还说得通，就是没写出人物。\n- 话里要有潜台词：人物很少直接说出心里话，常常答非所问、话里带刺或者欲言又止。想说的事绕着说，不想说的事岔开说。\n- 对话中穿插动作与停顿，避免一问一答地交代信息；一句话说到一半被打断、被别的声音盖过去，比说完整更像人。\n- 对白不承担大段的交代：重伤的人、赶路的人、对立的人说不了长话，更不会把十年前的布局、铁矿与官弩的来龙去脉讲得清清楚楚。前情最多带一两句，其余靠动作、前文与别人的反应带出；读者需要知道的，可以留到人物有闲、有理由开口的那一章。\n- 对话的分量：武侠与网文里人物说出来的话一般占全章两三成到四成多，只有纯打斗、独行与环境章才少。本章计划里写了对话多少就按它写；一章里只有动作与感官描写、人物几乎不开口，读者会觉得这些人像木偶。\n- 口语：对白要像嘴里说出来的，不像写出来的——用口语的词、省略的句子、称呼与语气词；叙述里不该有的套话，对白里更不该有。\n",
  "foreshadow": "---\nname: foreshadow\ndescription: \"伏笔埋设与回收：埋设时只写可观察的细节、不点明，回收时与前文相互印证，“不得说破”的内容一字不露。章节计划里有要埋或要收的伏笔、或有不得说破的内容时使用。\"\nmetadata:\n  title: \"伏笔埋设与回收\"\n  version: \"2\"\n  order: \"1\"\n---\n\n埋设伏笔时只写可以观察到的现象或细节，混在日常的动作与对话里，不点明它的意义，人物与叙述都不评论它。\n回收伏笔时让揭晓与前文的细节相互印证，读者回头去看能找到依据。\n本章“不得说破”的内容，一个字也不要写出来，也不要写出能直接推出它的话。\n",
  "no-adverbs": "---\nname: no-adverbs\ndescription: \"不用副词：不写“愤怒地说”“轻轻地推开”这类“……地”加动作，不贴情绪标签，不用“非常”“十分”撑形容词；换成准确的动词，或者写出读者看得见、听得见的动作、神情与声音。写每一章都用，写对话与动作时尤其要用。\"\nmetadata:\n  title: \"不用副词\"\n  version: \"1\"\n  order: \"10\"\n---\n\n当面说话时，听的人看得见表情与手势，听得见语气，也知道两人的关系与前因后果，所以“他很生气地说”听得懂。写在纸上，这些都没有了：“他愤怒地对她说”，是吼出来的，还是压着嗓子一字一顿？两种读法会让读者对这场戏得出两种结论。读者只好停下来猜，一停就出了故事；要费劲才能留在故事里，书就放下了。副词还多占一个词，句子慢一拍。\n\n- 动作：用一个本身就准确的动词，不用“副词＋动词”。“慢慢地走”写成挪、踱、蹭；“飞快地跑”写成冲、窜；“大声地说”写成喊、吼；“轻轻地关上门”写成掩上门。\n- 情绪：不在动作前贴“愤怒地、兴奋地、得意地、无奈地、温柔地”这类标签。写出能看见、能听见的东西，让读者自己看出情绪：与其写“他愤怒地说：‘出去。’”，不如写“他把茶碗往桌上一顿：‘出去。’”\n- 对话：说话的动词用“说”“问”，或者不加；语气靠话本身和前后的动作带出来，不靠“冷冷地”“淡淡地”。\n- 程度：不用“非常、十分、特别、极其、无比、格外”去撑形容词。换一个更准的词，或者用一个具体的细节说明到了什么地步：与其写“天非常冷”，不如写“砚台里的墨结了一层冰”。\n- 不在此列：“不、没、别、都、也、还、就、才、又、再、已经、正在”这类表示否定、范围、时间与先后的词照常用，它们说的是事实，不是含糊的修饰。\n",
  "pacing": "---\nname: pacing\ndescription: \"详略与节奏：改变局面的时刻展开写，过场与重复略写，同样的拉锯不写两遍。每一章都用。\"\nmetadata:\n  title: \"详略与节奏\"\n  version: \"2\"\n  order: \"2\"\n---\n\n改变局面的时刻要展开写：新信息出现、人物做出抉择、冲突升级、关系发生变化。放慢到动作、感官与心理的细节。\n过场、赶路、等待与重复的来回略写成一两句，或者直接省去。\n同样的拉锯不要写两遍；第二次出现时，必须有新的筹码、让步或代价。\n",
  "polish": "---\nname: polish\ndescription: \"润色与去 AI 味：不写“不是……而是……”“不仅……更是……”的对照壳子，不用一句话收尾替读者下结论，不把平常的事说成格言与命运；排比、三段式、重复开头、破折号与限定词只在意思需要时用；去掉“进行＋动词”、层叠的“的”、堆叠的被字句与四字词；最近几章用得太多的词与固定的感官搭配换成具体的动作，不拿同义词替换规避的说法；对白不交代前情，打斗不走固定步骤；修订时只改表达，不改事实、不添细节、不删伏笔。写完与修订时都用。\"\nmetadata:\n  title: \"润色与去 AI 味\"\n  version: \"4\"\n  order: \"8\"\n---\n\n模型写出来的文字有一股味道：替读者宣布什么重要、什么深刻，用整齐的句式撑场面，用套话收尾，几百章翻来覆去用同一批词和同一组感官。读者一闻到这股味道就出戏。下面是最常见的痕迹，写的时候绕开，修订时按它们查。单个词、一处排比不是问题；成串出现、每章都有，才是。\n\n- 对照壳子：“不是……而是……”“不仅是……更是……”“与其说……不如说……”，否定的那一半往往没人说过，只是为了把肯定的一半抬高。直接写成立的那一面；只有两半都带信息、或者否定的是人物真的误会了的事，才保留。\n- 一句话收尾：段末补一句总结、感悟或点题（“这一刻，她明白了”“这就是他要的答案”），是替读者下结论。停在动作、对白或一个具体的东西上。短句可以用，但要带新的事实或后果，不是把上一句再说一遍。\n- 伪深度与拔高：平常的事不说成格言（“信任是最贵的货币”），不往命运、宿命、注定、新的篇章上拔。写具体发生了什么。\n- 戏剧化碎片与凑数的排比：“没有风。没有灯。没有人。”这样一串碎片，连着三个以上的“没有……”，三件事凑成的排比，都是按公式排节奏。意思需要几项就写几项，不凑三。\n- 重复开头：接连几句都以同一个词起头（“他……。他……。他……”；“沈某没有……”一本书里出现几百次），合并成一句，或者换主语、从动作或环境写起。有意为之的排比例外，一章里不能到处都是。\n- 破折号与限定词：破折号用来解释、插入或转折，不拿它代替想清楚两个分句的关系，一章里不要连着用。“似乎有些”“仿佛有一种……的感觉”“某种难以言说的”这类堆叠的限定，留一个或者删掉，写出具体是什么。\n- 中文的几种冗余：“进行了一次深呼吸”写成“深吸一口气”，“进行＋动词”换成动词本身；层叠的“的”（“那个穿着灰色长衫的坐在角落里的老人”）拆开，或者用动作带出；一句话里不堆被字句，施事者清楚就改主动；四字词不接连排比（“风雨飘摇、人心惶惶、危机四伏”），留最准的一个，或者换成一个具体细节。\n- 用得太多的词与固定搭配：一个词、一组感官搭配（指骨泛白、喉头腥甜、把血咽下、空气里浮出杀意）在前几章已经用过很多次，这一章就不要再用；写手拿到的“文风账本”里列了最近用得太多的说法，照单避开。东西必须提到时换一个说法指代（“断刀”可以是“刀”“那截铁”“手里的东西”），感觉换成这个人物此刻独有的反应。\n- 不拿同义词替换规避的说法：“仿佛”被禁了就写“如同”“宛若”，毛病原封不动，还多了一个词的指纹。规避的说法一律换成具体的动作、神情、声音或东西，不换词。\n- 口癖：“嘴角勾起一抹弧度”“眼中闪过一丝”“倒吸一口凉气”“不禁”“仿佛”“空气仿佛凝固了”“鬼使神差”“涌上心头”之类，每处都换成这个人物此刻具体的动作、神情或声音。规避词表里的说法同此。\n- 形容与解释：能用动作与细节表现的，就不用形容词和心理描述去解释；同一段里同一个意思不换着说法说两遍。\n- 对白交代与固定步骤：重伤、仓促、对立的人把前因后果讲得清清楚楚，是作者借人物的嘴交代，改成一两句加动作与反应；打斗按“强敌出现、以伤换命、旧伤发作、强撑破局”推进的，改成这一场独有的转折（见“张力与冲突”）。\n- 修订的边界：修订一段时只改表达。不添原文没有的事实、名字、数字与感官细节，不改人物知道什么、做了什么，不删伏笔与“不得说破”之外的信息；人物对白里的口头禅、重复与病句是人物的，不改。改完读一遍，确认事实、时间、因果与前后文还接得上。\n",
  "pov": "---\nname: pov\ndescription: \"视角控制：只写视角人物能知道与推测的事，他人的心思只通过言行表现，不用全知旁白。每一章都用，尤其是有秘密与误会的章节。\"\nmetadata:\n  title: \"视角控制\"\n  version: \"2\"\n  order: \"6\"\n---\n\n只写视角人物能看见、听见、知道和推测的事。别人的心思只能通过他们的言行与神情表现出来。\n不要用全知的旁白揭示视角人物不知道的事；视角人物的猜测要写成猜测。\n",
  "scene": "---\nname: scene\ndescription: \"场景与感官：用具体物件与多种感官建立场景，环境服务于人物此刻的处境与心境。开场、换场或需要建立氛围时使用。\"\nmetadata:\n  title: \"场景与感官\"\n  version: \"2\"\n  order: \"4\"\n---\n\n用具体的物件与动作建立场景，不只写看见的，也写听见、摸到、闻到的。\n环境描写服务于人物此刻的处境与心境，不单独铺陈天气与景色。\n",
  "snowflake": "---\nname: snowflake\ndescription: \"雪花写作法：从一句话的故事出发逐层展开——一段话的梗概（开端、三次越来越重的挫折、结局）、主要人物的动机、目标、冲突与领悟、分段的大纲，再拆成一场场戏组成的章节计划；后一层只在前一层上加细节，不推翻前一层。生成作品骨架（大纲与人物）和章节计划时使用。\"\nmetadata:\n  title: \"雪花写作法\"\n  version: \"1\"\n  order: \"9\"\n  stages: \"planning\"\n---\n\n像雪花从一个小三角一圈圈长出枝杈那样规划：先定最小的骨架，再一层层加细节。后一层只在前一层的基础上展开，不另起炉灶；展开时发现前一层不对，就回头改前一层，让各层始终说的是同一个故事。\n\n一句话：用二三十字说清整个故事——一个什么样的人（用身份，不用名字），想要什么，什么拦着他。简介的第一句就是这句话。\n\n一段话：开端交代人物与处境，接着是三次越来越重的挫折，最后是结局。\n- 第一次挫折约在全书四分之一处，由主角在开端做的选择引出，让他回不到原来的生活。\n- 第二次挫折在全书中间，常常是主角发现原来的目标或判断错了，不得不换一个办法。\n- 第三次挫折约在四分之三处，把主角逼到绝境，逼他做出决定全书走向的抉择。\n- 结局写这个抉择的后果，回应一句话里的那个愿望：得到了、失去了，或者得到的和想的不一样。\n大纲分段写时，开端以第一次挫折收尾，发展以第二次挫折收尾，高潮从第三次挫折写到主角的抉择，结局写抉择的后果。\n\n人物：每个主要人物写清四样——动机（抽象的：想成为什么样的人、要守住什么）、目标（具体的：在这本书里要拿到或做成什么）、冲突（什么人或什么事拦着他）、领悟（到结尾明白了什么、变成了什么样）。反派也有自己的动机与目标，在他自己看来是对的。挫折从人物目标的相互碰撞里来，不靠天灾与巧合。\n\n拆成章节：按大纲的顺序拆，三次挫折分别落在全书约四分之一、一半与四分之三处的章节。每章都要推动三次挫折中的一条线，或者推动某个人物走向他的领悟；什么也不推动的章节并进别的章或者删掉。\n- 每章写明视角人物：这一章从谁的眼睛看。\n- 一章的情节点按“场景—后续”排。场景：视角人物带着一个目标行动，遇到冲突，以挫折收尾（没得到；得到了却更糟；或者付出了代价）。后续：他对挫折的反应、面前的两难与做出的决定，这个决定就是下一场戏的目标。\n- 紧张的章节多写场景、后续一笔带过；舒缓的章节把后续写足，让人物与读者喘口气。\n",
  "tension": "---\nname: tension\ndescription: \"张力与冲突：每场戏都有人想要什么并受到阻碍，阻力逐步加码，不用巧合化解冲突，威胁要兑现；打斗按这一场的地形、兵器、伤势与各人的目的写，不走固定步骤，每一场的转折不一样。写有对抗、谈判、危机或打斗的场景时使用。\"\nmetadata:\n  title: \"张力与冲突\"\n  version: \"3\"\n  order: \"3\"\n---\n\n每一场戏里都要有人想要什么，并且受到阻碍；阻力要一步步加码。\n冲突最紧的时候，不要用巧合、客气话或突然的善意把它化解掉。\n说出口的威胁要有分量，后面要兑现或者付出代价。\n\n打斗与对抗：\n\n- 按这一场的具体情形写：在哪里打（屋顶、窄巷、船上、雪坡），用什么打（刀、拳、暗器、桌椅），各人带着什么伤、想要什么（杀人、脱身、拖延、护住谁）。这些决定了每一步，不是从一个固定的模子里取。\n- 不走固定步骤：强敌出现、以伤换命、旧伤发作、强撑破局——这一套在一本书里出现两次读者就看穿了。每一场的转折要来自这一场独有的东西：地形的变化、第三个人闯进来、兵器坏了、一句话让人分神、一方本来就不想赢。\n- 打斗里有输有赢也有不了了之；不是每一场都要主角命悬一线再翻盘，也不是每一场都要有人重伤。\n- 伤与痛写一两处就够，不每一下都写创口、腥甜与指骨泛白；读者更想知道的是局面怎么变。\n- 打斗里的话很短：喘不过气的人说不出整句，更说不出前情。\n",
  "writing-basics": "---\nname: writing-basics\ndescription: \"写作基本功：去掉“看见、听到、觉得、意识到”这类过滤词，让读者直接经历；一句之内、句与句、段与段之间都要有清楚的关系（解释、因果、转折、递进、时间、空间、承接）；按情绪安排长短句与句式；动词看方向、快慢、力度与画面的焦点；每段能用一句话说清它做了什么。写每一章都用，写完自查时尤其要用。\"\nmetadata:\n  title: \"写作基本功\"\n  version: \"1\"\n  order: \"11\"\n---\n\n这些是句子、段落层面的基本功，不管写什么题材都适用。写的时候照着写，写完按最后一条自查。\n\n- 过滤词：叙述里少用“看见、看到、听见、听到、闻到、感到、觉得、认为、意识到、察觉、发现、好像、看样子、以为”这类词。它们在读者和场景之间隔了一层，让读者看的是“人物在看”，不是人物看到的东西。与其写“她听见楼下有人在撬锁”，不如写“楼下传来撬锁的声音，一下，又一下”。结论也别替读者下：写出细节，让读者自己看出人物在怕、在等、在撒谎，自己得出的结论读者才信。\n- 一句之内的关系：动笔前想清这句话里几部分是什么关系——先总说再分说（解释），因果（先因后果，也可以果在前），转折，几件事并列，一层比一层重（递进，最重的放最后，次序不能随便换），有了条件才有结果。关系清楚，长句也不乱；关系说不清，就拆成两句。\n- 句与句的衔接：写下一句前问一句，它和上一句是什么关系——展开上一句、转过去、由此导致、还是时间往后走？每一句都要接住上一句，不要各说各的。\n- 段与段的衔接：换段时让读者知道是怎么过去的。可以按时间往后走（写明“三天后”，或者用“天快亮时”这类说法）；可以顺着逻辑转折或推进；可以顺着人物的视线换地方，由近到远、由低到高；也可以让下一段接住上一段末尾的一个词、一件东西或一个念头再往下写。\n- 连接词：中文靠意思把句子连起来，“因为、所以、但是、而且、于是”删掉后意思还连得上，就删掉。不要每句都挂一个连接词。\n- 长短句与节奏：长句用来铺开环境、交代一串接连发生的动作，短句用来落下结论、制造力量或加快节奏。长句长在信息多——一个主语带出几个接连的动作，或者在中心词前后加上限定——不是把话说啰嗦。短句砍掉修饰只留主干，“非常、十分、特别、我觉得”这类口水词先删。一般写了两三个长句，就该有一个短句收住；但没有固定公式，看这里要铺陈还是要力量。\n- 句式跟着情绪变：平静时用陈述句；情绪起来，可以从陈述转到疑问，再到反问；紧张的时刻短句一句一顿，动作停不下来时用一个长句连着写，最后用一个短句落地。陈述、疑问、反问、整齐的对句与松散的句子交替着用，不要一整段都是同一种句子。\n- 动词的方向：动词里带着来路。“走回门口”暗示人之前离开过门口，前文没写过，读者就会卡住；只是到门口，写“走到门口”。灶膛里“冒”烟，是从一个口子往外出；炊烟“升”起，是一直往上；湖面“起”雾，是整片从无到有地生出来。按画面选。\n- 动词的快慢：有的动词带过程，有的是一下完成的。要写一瞬间的变化，用一下完成的说法（“门一开，屋里就静了”），不要用带着过程的写法（“门慢慢被推开以后，屋里渐渐静了下来”）。\n- 动词的力度：力度要和人物当时的处境相称。同一个人进门，占着理时一把推开，心虚时推开一道缝侧身挤进来，一个动词就写出了处境的变化。\n- 动词与画面的焦点：同一个动作有几个说法时，选能把读者的眼睛引到你要写的那样东西上的那个。写箭扎进靶心后尾羽还在颤，用“钉”，不用“射”——“射”把眼睛引到飞的过程上了。也留意动词的褒贬，别让它带出你不想要的态度。\n- 一句话说清：写完一段，试着用一句话概括它做了什么——留下主干，用一个概括的词代替一串细节。说不出来，这段就散了；说出来的和本章计划里的这一步对不上，就是跑题了。整章的各段概括连起来，应当就是本章的计划。\n- 读一遍：写完默读一遍，读着拗口、喘不过气或者一路平板的地方，就是长短与节奏要调的地方。\n",
};
